<?php else:?><?php if(!$edit&&!has_permission('blog.posts.create')):?><div class="error">You do not have permission to create blog posts.</div><?php else:?><div class="blog-editor-layout"><section class="card"><div class="blog-head"><div><h3><?=$edit?'Edit Article':'Create Blog Article'?></h3><span>English, Urdu, bilingual and video-ready publishing.</span></div></div><form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_post"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><input type="hidden" name="existing_slug" value="<?=e($edit['slug']??'')?>"><div class="blog-form-two"><div><label>Language</label><select class="input" name="language"><?php foreach(['en'=>'English','ur'=>'Urdu','bilingual'=>'Bilingual'] as $k=>$v):?><option value="<?=$k?>" <?=($edit['language']??'en')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div><label>Post Type</label><select class="input" name="post_type"><option value="article" <?=($edit['post_type']??'article')==='article'?'selected':''?>>Article</option><option value="video" <?=($edit['post_type']??'')==='video'?'selected':''?>>Video Blog</option></select></div><div><label>Category</label><select class="input" name="category_id"><option value="">Uncategorized</option><?php foreach($categories as $c):?><option value="<?=e($c['id'])?>" <?=($edit['category_id']??0)==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><?php if($canAll):?><div><label>Author</label><select class="input" name="author_id"><?php foreach($authors as $a):?><option value="<?=e($a['id'])?>" <?=($edit['author_id']??$uid)==$a['id']?'selected':''?>><?=e($a['name'])?> · <?=e($a['role'])?></option><?php endforeach;?></select></div><?php endif;?></div><label>English Title</label><input class="input" name="title_en" value="<?=e($edit['title_en']??'')?>"><label>English Excerpt</label><textarea class="input" rows="2" name="excerpt_en"><?=e($edit['excerpt_en']??'')?></textarea><label>English Article</label><textarea class="input blog-body-editor" rows="12" name="body_en"><?=e($edit['body_en']??'')?></textarea><div class="blog-urdu"><label>Urdu Title</label><input class="input" dir="rtl" name="title_ur" value="<?=e($edit['title_ur']??'')?>"><label>Urdu Excerpt</label><textarea class="input" dir="rtl" rows="2" name="excerpt_ur"><?=e($edit['excerpt_ur']??'')?></textarea><label>Urdu Article</label><textarea class="input blog-body-editor" dir="rtl" rows="12" name="body_ur"><?=e($edit['body_ur']??'')?></textarea></div><div class="blog-form-two"><div><label>City</label><select class="input" name="city_id"><option value="">None</option><?php foreach($cities as $c):?><option value="<?=e($c['id'])?>" <?=($edit['city_id']??0)==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div><label>Linked Business</label><select class="input" name="business_id"><option value="">None</option><?php foreach($businesses as $b):?><option value="<?=e($b['id'])?>" <?=($edit['business_id']??0)==$b['id']?'selected':''?>><?=e($b['name'])?></option><?php endforeach;?></select></div></div><label>Tags</label><div class="blog-tag-checks"><?php foreach($tags as $tag):?><label><input type="checkbox" name="tag_ids[]" value="<?=e($tag['id'])?>" <?=in_array((int)$tag['id'],$editTagIds,true)?'checked':''?>> <?=e($tag['name'])?></label><?php endforeach;?></div><label>Video URL</label><input class="input" type="url" name="video_url" value="<?=e($edit['video_url']??'')?>"><label>Cover Image URL</label><input class="input" name="cover_image" value="<?=e($edit['cover_image']??'')?>"><label>Upload Cover</label><input class="input" type="file" name="cover_upload" accept="image/*"><div class="blog-form-two"><div><label>SEO Meta Title</label><input class="input" name="meta_title" value="<?=e($edit['meta_title']??'')?>"></div><div><label>Canonical URL</label><input class="input" type="url" name="canonical_url" value="<?=e($edit['canonical_url']??'')?>"></div></div><label>SEO Description</label><textarea class="input" rows="2" name="meta_description"><?=e($edit['meta_description']??'')?></textarea><div class="blog-form-two"><div><label>Status</label><select class="input" name="status"><?php foreach(['draft','scheduled','published','archived'] as $v):if(in_array($v,['scheduled','published'],true)&&!$canPublish)continue;?><option value="<?=$v?>" <?=($edit['status']??'draft')===$v?'selected':''?>><?=ucfirst($v)?></option><?php endforeach;?></select></div><div><label>Publish / Schedule</label><input class="input" type="datetime-local" name="published_at" value="<?=e(!empty($edit['published_at'])?date('Y-m-d\TH:i',strtotime((string)$edit['published_at'])):'')?>"></div></div><div class="blog-checks"><label><input type="checkbox" name="is_featured" <?=($edit['is_featured']??0)?'checked':''?> <?=$canPublish?'':'disabled'?>> Featured</label><label><input type="checkbox" name="comments_enabled" <?=($edit['comments_enabled']??1)?'checked':''?>> Allow Comments</label></div><button class="btn">Save Blog Post</button></form></section><aside class="card blog-editor-help"><h3>Editorial Workflow</h3><p><b>Blogger:</b> create and manage own posts. Publishing can remain with an Editor.</p><p><b>Editor:</b> manage all authors, categories, tags, comments and homepage widgets.</p><p><b>Admin:</b> unrestricted unless a custom role limits access.</p><?php if($edit&&$edit['status']==='published'):?><a class="btn ghost" target="_blank" href="/blog.php?slug=<?=urlencode((string)$edit['slug'])?>">View Public Article ↗</a><?php endif;?></aside></div><?php endif;?><?php endif;?><?php require __DIR__.'/../app/end.php';?>